<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
use InvalidArgumentException;

class HtmlLessonsSeeder extends Seeder
{
    public function run(): void
    {
        $records = [];
        $now = now();

        foreach ($this->courses() as $courseId => $lessons) {
            foreach ($lessons as $index => $lesson) {
                $records[] = [
                    'course_id' => $courseId,
                    'title' => $lesson['title'],
                    'slug' => $lesson['slug'],
                    'description' => $lesson['description'],
                    'content' => $this->content($lesson),
                    'lesson_order' => $index + 1,
                    'estimated_minutes' => $lesson['minutes'],
                    'created_at' => $now,
                    'updated_at' => $now,
                ];
            }
        }

        if (count($records) !== 48) {
            throw new InvalidArgumentException('HtmlLessonsSeeder must provide exactly 48 lessons.');
        }

        DB::table('lessons')->insert($records);
    }

    private function content(array $lesson): string
    {
        $objectives = $this->listItems($lesson['objectives']);
        $bestPractices = $this->listItems($lesson['best_practices']);
        $pitfalls = $this->listItems($lesson['pitfalls']);
        $code = htmlspecialchars($lesson['example'], ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');

        return '<h3>Requirements &amp; Tools</h3>'
            . '<p>Use Visual Studio Code and a modern web browser such as Chrome, Firefox, or Edge. Create a basic text-editing workspace, save the lesson exercise as an HTML file, and open it in the browser while keeping the source editor available.</p>'
            . '<p>Work in a clearly named project folder. Make a small edit, save, reload the browser, and compare the rendered result with the markup so that each change has an observable outcome.</p>'
            . '<h3>Lesson Objectives</h3><ul class="list-disc pl-5">' . $objectives . '</ul>'
            . '<h3>Main Lesson Content</h3>'
            . '<p>' . $this->escape($lesson['explanation']) . '</p>'
            . '<p>In a real page, begin with the user task and the information the page must communicate. Choose native HTML elements that express those relationships, keep the source order understandable, and verify the page in the browser as well as in the editor. HTML describes document structure and meaning; presentation and behavior should be added only when the content model is clear.</p>'
            . '<h4>Practical Example</h4><pre><code>' . $code . '</code></pre>'
            . '<h4>Best Practices</h4><ul class="list-disc pl-5">' . $bestPractices . '</ul>'
            . '<h4>Common Pitfalls to Avoid</h4><ul class="list-disc pl-5">' . $pitfalls . '</ul>'
            . '<h4>Practice</h4><p>' . $this->escape($lesson['practice']) . '</p>';
    }

    private function listItems(array $items): string
    {
        return implode('', array_map(
            fn (string $item): string => '<li>' . $this->escape($item) . '</li>',
            $items
        ));
    }

    private function escape(string $value): string
    {
        return htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
    }

