                    '<video controls width="1280" height="720" preload="none" poster="course-preview.jpg">\n  <source src="course-intro.mp4" type="video/mp4">\n</video>\n<img src="diagram-small.jpg" srcset="diagram-small.jpg 480w, diagram-large.jpg 960w" sizes="(max-width: 600px) 100vw, 600px" width="960" height="540" alt="Diagram of the lesson workflow">',
                    ['Set intrinsic dimensions and let presentation adapt to the container.', 'Avoid downloading large media before a user needs it.'],
                    ['Do not stretch media to a different aspect ratio.', 'Do not treat preload as a command that every browser must follow.'],
                    'Choose responsive image candidates and video loading hints for a course landing page viewed on mobile and desktop.'),
                $this->lesson('Embedding Media and External Players', 'html-media-embedding-external-players', 'Embed an external player with an accessible title, privacy awareness, and a fallback.', 23,
                    ['Give an iframe a meaningful title.', 'Use lazy loading for noncritical embeds.', 'Provide an alternative link and consider sandbox restrictions.'],
                    'An iframe embeds a separate browsing context, often used by third-party media players. The title tells users what the frame contains. Loading can be deferred for content below the fold. External players may set cookies, request permissions, or fail, so provide a direct resource link and review privacy and security requirements.',
                    '<section aria-labelledby="talk-title">\n  <h2 id="talk-title">Guest lecture</h2>\n  <iframe src="https://media.example.test/embed/42" title="Guest lecture video player" loading="lazy" allow="fullscreen; picture-in-picture"></iframe>\n  <p><a href="https://media.example.test/watch/42">Open the lecture on the media site</a></p>\n</section>',
                    ['Describe the frame purpose with a unique title.', 'Review provider permissions and third-party data behavior.'],
                    ['Do not embed untrusted pages without a security review.', 'Do not leave essential lecture content available only through the external player.'],
                    'Evaluate an external video embed and propose its title, fallback, loading behavior, and user privacy notice.'),
                $this->lesson('Media Project: A Complete Lesson Player', 'html-media-complete-lesson-player', 'Combine video, captions, transcript, responsive dimensions, and a resilient fallback.', 30,
                    ['Plan the media information and its alternatives.', 'Combine video, source, and timed text markup.', 'Review keyboard use, performance, and fallback behavior.'],
                    'A production-ready media section places the player in context: a heading explains its purpose, the poster previews it, tracks provide captions, and a transcript remains available independently. The page should still communicate the lesson if playback is unsupported or delayed. Test controls, focus order, caption selection, and the visual layout at narrow widths.',
                    '<section aria-labelledby="lesson-video-title">\n  <h2 id="lesson-video-title">How a rain garden works</h2>\n  <video controls width="1280" height="720" poster="rain-garden.jpg" preload="metadata">\n    <source src="rain-garden.mp4" type="video/mp4">\n    <track kind="captions" src="rain-garden-en.vtt" srclang="en" label="English captions" default>\n    <p><a href="rain-garden-transcript.html">Read the transcript</a></p>\n  </video>\n  <p><a href="rain-garden-transcript.html">Open the complete transcript</a></p>\n</section>',
                    ['Keep the transcript available outside the player fallback.', 'Check video ratio, captions, focus, and data use on real devices.'],
                    ['Do not duplicate or omit alternatives when media is embedded.', 'Do not publish a track file without confirming its timing and language.'],
                    'Build a media lesson section for a short instructional clip and submit a checklist covering captions, transcript, fallback, and performance.'),
            ],
            8 => [
                $this->lesson('Landmarks: Header, Nav, Main, and Footer', 'html-semantics-page-landmarks', 'Create recognizable page landmarks and label multiple navigation regions.', 22,
                    ['Mark page header, main content, navigation, and footer.', 'Use one primary main region for the document.', 'Label navigation landmarks when there are several.'],
                    'Landmark elements provide shortcuts through the large regions of a page. Header and footer can apply to the page or a section; nav identifies a significant navigation region; main marks the dominant page content. Multiple nav regions should have distinct accessible names so users can choose the right set of links.',
                    '<header><a href="/">Northside Library</a></header>\n<nav aria-label="Primary navigation"><a href="/events">Events</a><a href="/catalog">Catalog</a></nav>\n<main><h1>Upcoming events</h1><p>Find a reading group or workshop.</p></main>\n<footer><nav aria-label="Footer navigation"><a href="/accessibility">Accessibility</a></nav></footer>',
                    ['Keep the DOM order aligned with reading order.', 'Give repeated landmark types unique labels.'],
                    ['Do not wrap minor link groups in nav without a navigation purpose.', 'Do not place multiple unrelated main elements in one page.'],
                    'Map the landmarks for a library page with primary navigation, in-page navigation, main content, and policy links.'),
                $this->lesson('Sections, Articles, and Asides', 'html-semantics-sections-articles-asides', 'Choose sectioning elements according to thematic grouping and content independence.', 23,
                    ['Use section for a themed group with a heading.', 'Use article for self-contained content.', 'Use aside for related supporting information.'],
                    'Section introduces a thematic part of a document and normally has a heading. Article is appropriate when content can be understood and reused independently, such as a post or announcement. Aside holds supporting information related to nearby content but not essential to its primary flow. These distinctions describe editorial relationships, not visual card shapes.',
                    '<main><h1>Community journal</h1><section><h2>Latest reports</h2><article><h3>New walking path opens</h3><p>The riverside path is now accessible from the east gate.</p></article></section><aside><h2>Related</h2><a href="/maps">Trail map</a></aside></main>',
                    ['Give sections headings that name their subject.', 'Use article for content that has a coherent standalone identity.'],
                    ['Do not use section as a generic styling wrapper.', 'Do not move required instructions into aside merely to visually separate them.'],
                    'Classify article summaries, related links, and thematic page regions for a neighborhood news page.'),
                $this->lesson('Heading Order and Reading Structure', 'html-semantics-heading-order-reading', 'Build a navigable heading outline that reflects the page hierarchy.', 21,
                    ['Create a coherent h1-to-subheading outline.', 'Keep headings descriptive and concise.', 'Check that visual order and DOM order agree.'],
                    'Headings let readers preview a page and let assistive technology jump between sections. The level signals nesting: h2 headings divide the main topic, and h3 headings subdivide an h2. A good outline can be understood without styles and should follow the logical reading sequence presented to users.',
                    '<main><h1>Volunteer Handbook</h1><section><h2>Before your shift</h2><h3>Check in</h3><p>Sign in at the welcome desk.</p><h3>Prepare materials</h3><p>Collect the supplies listed for your activity.</p></section><section><h2>During your shift</h2><p>Ask a coordinator when priorities change.</p></section></main>',
                    ['Use unique, useful headings rather than repeated vague labels.', 'Check the outline in source order and at narrow viewport sizes.'],
                    ['Do not skip from h2 to h5 to achieve a smaller font.', 'Do not use headings for text that is not a section title.'],
                    'Repair a handbook outline with skipped levels and vague headings, then justify the new hierarchy.'),
                $this->lesson('Accessible Links and Images', 'html-semantics-accessible-links-images', 'Make links and images understandable when encountered outside their surrounding layout.', 23,
                    ['Write link names that communicate their destination.', 'Provide purposeful alternatives for informative images.', 'Use empty alt for decorative images.'],
                    'Assistive technology can present links and images in lists without surrounding prose. Link text should identify the destination or action. Alternative text should convey the information relevant to the page task rather than mechanically describe every visible detail. A decorative image can use alt="" so it does not add noise.',
                    '<p>Compare options in the <a href="/plans">membership plan guide</a>.</p>\n<figure><img src="accessible-ramp.jpg" alt="A gently sloped ramp leading to the west entrance" width="720" height="420"><figcaption>Step-free access is available at the west entrance.</figcaption></figure>\n<img src="flourish.svg" alt="">',
                    ['Review image alternatives in context with captions and nearby text.', 'Make each link understandable when read on its own.'],
                    ['Avoid generic link text such as more or here.', 'Do not omit alt on informative images or describe decorative flourishes aloud.'],
                    'Audit five links and three images on a page, rewriting names and alternatives so each purpose is clear.'),
                $this->lesson('Accessible Tables and Data', 'html-semantics-accessible-tables-data', 'Expose table relationships using captions, header cells, and scope.', 24,
                    ['Use tables only for relational data.', 'Add caption and header cells.', 'Associate row and column labels with scope.'],
                    'A data table is a two-dimensional relationship between headers and values. Caption supplies a table name; thead and tbody clarify groups; th identifies a header; scope associates a header with a row or column. For a complex table, consider simpler tables or explicit header identifiers so relationships remain navigable.',
                    '<table>\n  <caption>Library opening hours</caption>\n  <thead><tr><th scope="col">Day</th><th scope="col">Opens</th><th scope="col">Closes</th></tr></thead>\n  <tbody><tr><th scope="row">Monday</th><td>09:00</td><td>18:00</td></tr><tr><th scope="row">Tuesday</th><td>09:00</td><td>20:00</td></tr></tbody>\n</table>',
                    ['Keep tables simple and identify every row or column.', 'Provide a summary nearby when relationships are complex.'],
                    ['Do not use table markup to position unrelated content.', 'Do not use td where a row or column heading is needed.'],
                    'Turn a weekly schedule into an accessible table with a caption, days as row headers, and clearly labeled time columns.'),
                $this->lesson('Forms, Labels, and Error Semantics', 'html-semantics-accessible-form-labels-errors', 'Structure form controls so labels, instructions, groups, and errors are programmatically connected.', 25,
                    ['Associate every control with a label.', 'Group related choices with fieldset and legend.', 'Connect help or error text to its field.'],
                    'A control needs an accessible name, commonly provided by label. Fieldset and legend give context to related choices. Help and error messages should be nearby and connected with aria-describedby when needed. Required status and error state need text or programmatic communication rather than color alone.',
                    '<fieldset><legend>Delivery method</legend><label><input type="radio" name="delivery" value="pickup" required> Pick up in store</label><label><input type="radio" name="delivery" value="ship"> Ship to address</label></fieldset>\n<label for="postal">Postal code</label><input id="postal" name="postal" aria-describedby="postal-help postal-error" required><p id="postal-help">Use the code for your delivery address.</p><p id="postal-error" role="status">Enter a valid postal code.</p>',
                    ['Keep instructions available before and during entry.', 'Make error messages specific and connected to affected controls.'],
                    ['Do not use placeholder as the only control name.', 'Do not indicate invalidity only with red borders or icons.'],
                    'Design the accessible structure and error relationships for a delivery form with address fields and a delivery choice.'),
                $this->lesson('ARIA and Native HTML Semantics', 'html-semantics-aria-native-html', 'Use native HTML first and add ARIA only when it communicates a necessary custom state.', 26,
                    ['Explain when native HTML already supplies semantics.', 'Use labels and state attributes consistently.', 'Keep dynamic ARIA state synchronized with the UI.'],
                    'ARIA changes the accessibility information exposed by an element but does not add browser behavior such as keyboard handling or focus management. A native button is usually better than a clickable div because it already supports keyboard interaction. For custom disclosure controls, aria-expanded must reflect the visible state and aria-controls can identify the affected region.',
                    '<button type="button" aria-expanded="false" aria-controls="shipping-details">Shipping details</button>\n<section id="shipping-details" hidden><h2>Shipping details</h2><p>Orders ship within two working days.</p></section>',
                    ['Prefer native buttons, inputs, and links.', 'Test keyboard behavior and verify that announced state matches visible state.'],
                    ['Do not add redundant roles to native controls.', 'Do not use ARIA attributes as a substitute for implementing interaction behavior.'],
                    'Review a custom disclosure mockup and specify its native element, keyboard behavior, expanded state, and controlled region.'),
                $this->lesson('Accessibility Audit and Page Build', 'html-semantics-accessibility-audit-project', 'Apply semantic structure and an accessibility review to a complete informational page.', 30,
                    ['Combine landmarks and a logical heading structure.', 'Check names and alternatives for links, images, and controls.', 'Test the page with keyboard-only navigation.'],
                    'An accessibility review begins with meaningful HTML and verifies the experience using more than automated scans. Inspect the outline, landmark names, link purpose, image alternatives, form labels, focus order, and zoom behavior. Record issues by user impact and verify each correction in the rendered page and accessibility tree.',
                    '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Accessible Workshop</title></head><body><header><nav aria-label="Primary">...</nav></header><main><h1>Accessible workshop</h1><section><h2>Schedule</h2>...</section><section><h2>Register</h2><form>...</form></section></main><footer>...</footer></body></html>',
                    ['Test with keyboard, zoom, and at least one screen-reader workflow.', 'Fix the source semantics rather than layering visual workarounds.'],
                    ['Do not claim accessibility from an automated score alone.', 'Do not remove visible focus indicators without an equivalent replacement.'],
                    'Build a workshop page and submit an audit checklist for landmarks, heading order, image alternatives, forms, keyboard flow, and zoom.'),
            ],
            11 => [
                $this->lesson('Document Head and Metadata Strategy', 'html-advanced-head-metadata-strategy', 'Organize document metadata for encoding, responsive display, search descriptions, and ownership.', 24,
                    ['Order essential metadata near the start of head.', 'Write a unique title and description.', 'Add a canonical link when duplicate URLs exist.'],
                    'The head communicates document identity and rendering hints. Character encoding should be declared early; viewport metadata supports responsive layouts; title identifies the page in tabs and search results; description summarizes the visible content. Canonical URLs indicate a preferred address when equivalent content can be reached through several paths.',
                    '<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>HTML Structure Guide | LearnWeb</title>\n  <meta name="description" content="A practical guide to semantic HTML page structure.">\n  <link rel="canonical" href="https://learnweb.example/guides/html-structure">\n</head>',
                    ['Make metadata accurate, unique, and consistent with page content.', 'Confirm that canonical URLs use the intended public origin.'],
                    ['Do not duplicate the same title and description across unrelated pages.', 'Do not expect metadata to compensate for thin or confusing visible content.'],
                    'Write the head for a course article with a specific title, summary, viewport, encoding, and preferred URL.'),
                $this->lesson('Responsive and Progressive Metadata', 'html-advanced-responsive-progressive-metadata', 'Set viewport and theme hints while designing pages that remain useful without enhancement.', 22,
                    ['Use viewport metadata for device-width layouts.', 'Understand theme-color as a browser hint.', 'Preserve a working document without optional scripts.'],
                    'Viewport metadata tells mobile browsers to use the device width rather than a wide virtual canvas. Theme-color can suggest browser chrome color, but it does not control page appearance. Progressive enhancement begins with useful semantic content and links, then adds optional behaviors without making the document inaccessible when scripts or external resources fail.',
                    '<meta name="viewport" content="width=device-width, initial-scale=1">\n<meta name="theme-color" content="#14566b">\n<main><h1>Trail conditions</h1><p>All listed paths were checked this morning.</p><a href="/trails/map">View the printable trail map</a></main>',
                    ['Keep essential content in the document itself.', 'Test at narrow widths and with browser text zoom.'],
                    ['Do not disable user zoom with restrictive viewport settings.', 'Do not treat browser chrome hints as a replacement for page colors or contrast.'],
                    'Prepare responsive metadata and a useful no-script page outline for a trail conditions service.'),
                $this->lesson('Custom Data Attributes and Safe Values', 'html-advanced-data-attributes', 'Use data attributes as small public hooks for progressive enhancement.', 20,
                    ['Name custom attributes with the data- prefix.', 'Read data only as public, untrusted input.', 'Prefer semantic attributes when HTML already provides a meaning.'],
                    'The data-* family attaches custom strings to an element and is exposed through the DOM dataset API. It can connect a control to a non-sensitive identifier or enhancement behavior. Data attributes are part of the delivered markup and can be inspected or edited by users, so authorization and trusted values belong on the server.',
                    '<button type="button" data-action="expand" data-panel-id="hours-panel" aria-controls="hours-panel" aria-expanded="false">Show hours</button>\n<section id="hours-panel" hidden><h2>Opening hours</h2><p>Monday to Friday, 9 AM to 5 PM.</p></section>',
                    ['Keep data names stable and specific.', 'Use native href, type, and value attributes when they express the relationship.'],
                    ['Do not store API secrets, permissions, or trusted prices in data attributes.', 'Do not treat an attribute as a substitute for keyboard interaction or accessible state.'],
                    'Specify the public data hooks needed for a collapsible schedule and identify which state still needs to be managed by the application.'),
                $this->lesson('Templates and Repeated Content Structure', 'html-advanced-template-element', 'Define inert reusable markup with template and keep repeated content meaningful.', 23,
                    ['Understand that template content is not rendered by default.', 'Give repeated content a stable semantic structure.', 'Plan an accessible fallback for script-generated items.'],
                    'The template element stores a fragment that scripts can clone later. Its content is inert until inserted into the document. Templates can reduce duplicated client-side markup, but they do not fetch data or create an accessible experience by themselves. A page should preserve a useful initial state and ensure inserted controls receive labels, names, and focus behavior.',
                    '<template id="event-card">\n  <article class="event-card">\n    <h2></h2>\n    <p></p>\n    <a>View event</a>\n  </article>\n</template>\n<div id="events" aria-live="polite"><p>Choose a date to load events.</p></div>',
                    ['Keep the template structure complete and semantic.', 'Provide status feedback when content is inserted asynchronously.'],
                    ['Do not expect template content to appear without script insertion.', 'Do not create repeated headings with no relationship to their containing page.'],
                    'Design a reusable event item template and describe the accessible loading, empty, and populated states around it.'),
                $this->lesson('Iframes, Sandbox, and Embed Boundaries', 'html-advanced-iframe-sandbox', 'Contain embedded documents with a title, deliberate permissions, and useful fallback.', 26,
                    ['Name an iframe with title.', 'Choose sandbox permissions based on required behavior.', 'Provide a direct link when an embed cannot load.'],
                    'An iframe loads a separate document with its own navigation and scripts. Sandbox starts with restrictive behavior and individual permissions can be added only when necessary. The title gives the frame an accessible name. External content introduces privacy, security, performance, and availability considerations that should be documented.',
                    '<section aria-labelledby="schedule-heading">\n  <h2 id="schedule-heading">Live schedule</h2>\n  <iframe src="/public-schedule" title="Public workshop schedule" sandbox="allow-scripts" loading="lazy" width="800" height="500"></iframe>\n  <p><a href="/public-schedule">Open the schedule as a page</a></p>\n</section>',
                    ['Add only the iframe permissions the integration requires.', 'Explain embedded content and preserve a normal link fallback.'],
                    ['Do not combine powerful sandbox permissions without reviewing the trust boundary.', 'Do not let a frame become the only route to essential information.'],
                    'Evaluate an embedded scheduling widget and specify its title, sandbox requirements, loading policy, and non-embedded alternative.'),
                $this->lesson('Details, Summary, and Native Disclosure', 'html-advanced-details-summary', 'Build a browser-native disclosure for optional content with a clear summary label.', 20,
                    ['Use summary as the first child of details.', 'Write a summary that communicates the hidden content.', 'Decide whether the content should start open.'],
                    'Details creates a disclosure widget and summary provides its interactive label. The browser supplies basic keyboard behavior and expanded state, making it simpler and more robust than a custom clickable container. Keep the summary understandable on its own and avoid hiding information users need to complete the primary task.',
                    '<details>\n  <summary>Shipping and returns</summary>\n  <p>Orders ship within two working days. Unused items can be returned within 30 days.</p>\n</details>\n<details open>\n  <summary>Workshop materials</summary>\n  <p>Bring a notebook; all other supplies are provided.</p>\n</details>',
                    ['Use the native element when a simple disclosure is sufficient.', 'Test keyboard activation and the expanded indicator.'],
                    ['Do not put a non-interactive heading before summary inside details.', 'Do not hide critical terms in an unlabeled disclosure.'],
                    'Create three disclosures for a course FAQ and ensure each summary clearly identifies the information it reveals.'),
                $this->lesson('Script Loading and Document Lifecycle', 'html-advanced-script-loading', 'Place scripts with loading attributes that preserve parsing and predictable behavior.', 25,
                    ['Compare deferred and asynchronous scripts.', 'Understand module script defaults.', 'Keep content useful if optional JavaScript fails.'],
                    'A classic script without a loading attribute pauses HTML parsing while it downloads and executes. Defer downloads in parallel and runs after parsing, in document order; async runs as soon as available and is best for independent scripts. Module scripts are deferred by default. The choice affects execution order and when the script can query document content.',
                    '<script src="/assets/navigation.js" defer></script>\n<script src="/assets/metrics.js" async></script>\n<script type="module" src="/assets/course-page.js"></script>',
                    ['Use defer when scripts depend on document order.', 'Load optional independent scripts without blocking essential content.'],
                    ['Do not use async for scripts that require a preceding script to execute first.', 'Do not depend on a script running before the markup it reads exists.'],
                    'Choose a loading strategy for an ordered UI script, an independent analytics script, and a module that enhances lesson markup.'),
                $this->lesson('Advanced Structure Integration Project', 'html-advanced-structure-integration-project', 'Design a robust document combining metadata, semantic regions, disclosures, and external content.', 30,
                    ['Plan the document outline and navigation.', 'Combine metadata, semantics, and progressive enhancement.', 'Document embed and script failure states.'],
                    'A complex page should still be a coherent document before any optional widgets are considered. Start with metadata and landmarks, establish a navigable heading outline, keep related articles together, and use disclosures for optional detail. Add external content and scripts only with clear permissions, loading behavior, and nonessential failure fallbacks.',
                    '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Research Field Guide</title><script type="module" src="/assets/guide.js"></script></head><body><header>...</header><main><h1>Research field guide</h1><article><section><h2>Methods</h2>...</section><details><summary>Equipment notes</summary>...</details></article><aside>...</aside></main><footer>...</footer></body></html>',
                    ['Build and validate semantic content before testing optional behavior.', 'Keep every external dependency named and explainable.'],
                    ['Do not add structure solely for visual layout.', 'Do not let optional scripts or embeds prevent access to the main document.'],
                    'Plan a research guide with metadata, landmarks, two articles, a disclosure, one external embed, and a written fallback for each dependency.'),
            ],
            12 => [
                $this->lesson('Plan a Page Around User Tasks', 'html-view-pages-plan-user-tasks', 'Turn an audience and page goal into a clear information outline before writing markup.', 20,
                    ['Identify the audience and primary task.', 'List information required to complete that task.', 'Create a heading outline before implementation.'],
                    'A real page starts with the reader rather than a list of tags. Define what visitors need to know or do, prioritize primary and supporting information, and sketch the page outline. This plan influences which regions, headings, links, media, and form controls will be appropriate.',
                    '<main>\n  <h1>Repair cafe</h1>\n  <section><h2>What we repair</h2><p>Small household items and clothing.</p></section>\n  <section><h2>When to visit</h2><p>First Saturday of each month.</p></section>\n  <section><h2>Book a place</h2>...</section>\n</main>',
                    ['Write the page purpose in one sentence.', 'Prioritize information based on the reader journey.'],
                    ['Do not begin with visual decoration before deciding the content hierarchy.', 'Do not make every section equally prominent when tasks differ in importance.'],
                    'Write a brief and content outline for a local service page, including the main visitor task and supporting questions.'),
                $this->lesson('Shared Site Header and Branding', 'html-view-pages-shared-header-branding', 'Create a recognizable header that identifies the site and introduces its main navigation.', 21,
                    ['Represent branding as useful text or a link.', 'Group primary navigation in a labeled nav landmark.', 'Keep header source order logical.'],
                    'A site header provides identity and orientation. A brand link commonly returns to the home page; a concise tagline can explain the service; a primary navigation group lists a few high-value destinations. The header should not become a catch-all for every utility action, especially on small screens.',
                    '<header>\n  <a href="/" aria-label="Harbor Learning home"><strong>Harbor Learning</strong></a>\n  <p>Practical classes for curious people</p>\n  <nav aria-label="Primary navigation"><a href="/classes">Classes</a><a href="/calendar">Calendar</a><a href="/about">About</a></nav>\n</header>',
                    ['Use consistent header markup across related pages.', 'Make each navigation destination clear and reachable.'],
                    ['Do not make a logo image the only accessible name for the site.', 'Do not include a duplicate, unlabeled copy of the primary menu.'],
                    'Build a shared header for three connected pages and explain how users identify the brand and reach the key sections.'),
                $this->lesson('Navigation Between Pages and Sections', 'html-view-pages-navigation', 'Connect a small site with useful page links and in-page anchors.', 22,
                    ['Use URLs that match the page or section destination.', 'Add stable ids for in-page navigation.', 'Indicate current page where appropriate.'],
                    'Multi-page navigation links to documents; in-page navigation links to fragments whose ids occur in the current document. A table of contents is useful on long pages when its targets have stable, descriptive ids. aria-current="page" can identify the active page in a navigation set.',
                    '<nav aria-label="Primary navigation"><a href="index.html">Home</a><a href="services.html" aria-current="page">Services</a><a href="contact.html">Contact</a></nav>\n<nav aria-label="On this page"><a href="#consulting">Consulting</a><a href="#training">Training</a></nav>\n<section id="consulting"><h2>Consulting</h2><p>...</p></section>\n<section id="training"><h2>Training</h2><p>...</p></section>',
                    ['Test links from every page and ensure fragment ids are unique.', 'Use current-page state only where the destination actually matches.'],
                    ['Do not use buttons for ordinary URL navigation.', 'Do not use unstable numeric fragments that break after content edits.'],
                    'Create primary navigation for a three-page site and in-page navigation for a long services page.'),
                $this->lesson('Landing Page Introduction and Hero Content', 'html-view-pages-landing-introduction', 'Write a focused page introduction with a meaningful heading and purposeful next action.', 22,
                    ['Use a heading that names the page offer or topic.', 'Pair supporting context with a useful next step.', 'Keep essential meaning in actual document content.'],
                    'A prominent introduction is a content region, not a special HTML element. Its heading should state the page topic or offer directly; supporting text explains the audience or outcome; links take users to related content while buttons trigger actions. An image can reinforce the message but should not contain information absent from text.',
                    '<main><section aria-labelledby="intro-title"><h1 id="intro-title">Learn to repair everyday objects</h1><p>Join a guided workshop, bring one item, and leave with practical skills.</p><p><a href="#schedule">View workshop dates</a> <a href="/register">Reserve a place</a></p></section><section id="schedule"><h2>Next workshop</h2>...</section></main>',
                    ['Make the heading specific and the next action explicit.', 'Keep important content available as selectable text.'],
                    ['Do not create competing page introductions with unrelated headings.', 'Do not rely on a background image to explain the offer.'],
                    'Write an introduction for a community class that states the offer, audience benefit, and a clear path to dates or registration.'),
                $this->lesson('Content Sections and Reusable Cards', 'html-view-pages-content-sections-cards', 'Structure repeated services or features consistently inside a meaningful section.', 24,
                    ['Give a collection a descriptive section heading.', 'Use article for independent repeated items where appropriate.', 'Keep repeated item structure consistent.'],
                    'A list of services or features needs an introduction and consistent item-level information. Article fits an item that has a meaningful standalone identity; list elements fit a simple collection. The important choice is the relationship between items and the surrounding topic, not whether the design uses cards or borders.',
                    '<section aria-labelledby="classes-title"><h2 id="classes-title">Choose a class</h2><article><h3>Woodworking basics</h3><p>Learn safe measuring, joining, and finishing.</p><a href="/classes/woodworking">See class details</a></article><article><h3>Textile mending</h3><p>Practice visible and invisible repairs.</p><a href="/classes/mending">See class details</a></article></section>',
                    ['Give each repeated item the same essential content pattern.', 'Use links that name the specific destination.'],
                    ['Do not use article for every visually boxed element automatically.', 'Do not repeat generic links whose destination is unclear.'],
                    'Mark up three course offerings with a shared title, summary, and destination, then explain whether each is an article or list item.'),
                $this->lesson('Contact Details and Inquiry Forms', 'html-view-pages-contact-details-forms', 'Provide direct contact methods alongside a labeled inquiry form.', 25,
                    ['Use address, mailto, and tel where appropriate.', 'Label form controls and state response expectations.', 'Collect only information needed to respond.'],
                    'A contact page can provide a physical address, hours, direct email and phone links, and a form. The address element groups contact information for the relevant organization. Form labels should remain visible, required status should be explicit, and the page should tell users what happens after submission.',
                    '<section aria-labelledby="contact-title"><h2 id="contact-title">Contact the studio</h2><address>18 Cedar Lane<br>Riverside</address><p><a href="mailto:hello@studio.example">Email the studio</a></p><p><a href="tel:+15550186">Call 555-0186</a></p><form action="/inquiries" method="post"><label for="contact-email">Your email</label><input id="contact-email" name="email" type="email" required><label for="question">How can we help?</label><textarea id="question" name="question" rows="5" required></textarea><button type="submit">Send inquiry</button></form></section>',
                    ['Explain how and when a response will arrive.', 'Use labels, validation, and a useful success state.'],
                    ['Do not request sensitive details without a clear need.', 'Do not provide a form with no submission feedback or privacy context.'],
                    'Build a contact section with address, business hours, direct contact links, and a two-field inquiry form.'),
                $this->lesson('Footer, Policies, and Secondary Navigation', 'html-view-pages-footer-secondary-navigation', 'Finish a web page with helpful secondary links and clear organization details.', 20,
                    ['Group secondary links by user purpose.', 'Use a footer landmark for closing page information.', 'Keep legal and accessibility information discoverable.'],
                    'The footer gives the page a predictable ending and can include contact details, policy links, organization ownership, or a secondary navigation. If there are several groups, short headings or labeled nav regions explain them. Footer structure should remain useful on every viewport and should not duplicate the entire primary menu without purpose.',
                    '<footer><nav aria-label="Company information"><a href="/about">About</a><a href="/contact">Contact</a></nav><nav aria-label="Policies"><a href="/privacy">Privacy</a><a href="/accessibility">Accessibility</a></nav><p>© 2026 Harbor Learning</p></footer>',
                    ['Keep labels consistent across pages.', 'Check keyboard access and link contrast in the footer.'],
                    ['Do not hide essential support links in an unlabeled dense list.', 'Do not leave stale copyright years or broken routes.'],
                    'Create a reusable footer for a small business site with company, support, and policy destinations.'),
                $this->lesson('Complete Multi-Page Website Project', 'html-view-pages-complete-website-project', 'Combine page planning, navigation, accessible content, contact details, and consistent shared regions.', 30,
                    ['Design a small site map with distinct page purposes.', 'Reuse header and footer patterns while keeping page content unique.', 'Audit the complete site for links and semantic structure.'],
                    'A complete website is a set of documents with shared identity and clear differences in purpose. Define a site map, create a unique title and h1 for every page, reuse shared navigation, and keep each main region focused. Finish by following every link, checking language and headings, reviewing media alternatives, and testing the interaction order with a keyboard.',
                    '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Harbor Learning | Home</title></head><body><header><a href="index.html">Harbor Learning</a><nav aria-label="Primary"><a href="classes.html">Classes</a><a href="about.html">About</a><a href="contact.html">Contact</a></nav></header><main><h1>Build practical skills together</h1><section><h2>Upcoming classes</h2>...</section></main><footer>...</footer></body></html>',
                    ['Give every page a distinct title, heading, and purpose.', 'Test the complete navigation graph rather than isolated pages.'],
                    ['Do not leave placeholder links or duplicate page titles.', 'Do not treat a successful visual render as the only quality check.'],
                    'Plan and implement a four-page site for a local learning center, then submit a page map and review checklist for semantics, navigation, accessibility, and content completeness.'),
            ],
        ];
    }

    private function lesson(
        string $title,
        string $slug,
        string $description,
        int $minutes,
        array $objectives,
        string $explanation,
        string $example,
        array $bestPractices,
        array $pitfalls,
        string $practice
    ): array {
        return compact('title', 'slug', 'description', 'minutes', 'objectives', 'explanation', 'example', 'bestPractices', 'pitfalls', 'practice') + [
            'best_practices' => $bestPractices,
        ];
    }
}